    /**
     * Sort an array of JPeptide objects based on peptide mass: from small to large.
     */
    private static final Comparator<JPeptide> comparator_peptide_mass = (s1, s2) -> {
        if (s1.getMass() < s2.getMass()) {
            return -1;
        } else if (s1.getMass() > s2.getMass()) {
            return 1;
        } else {
            return 0;
        }
    };


